it('Nullable, Array and Object', async () => {
  const Test = Model(
    { name: 'Test', key: ['id'] },
    {
      id: S.Int32(),
      nullable: S.Nullable(S.Boolean()),
      array: S.Array(S.String()),
      nestedArray: S.Array(S.Array(S.String())),
      object: S.Object({ a: S.Boolean() }),
    },
  );

  const { ts, sql } = await generatePostgresTest({ Test });
  expect(ts).toEqual(`import { boolean, integer, jsonb, pgTable, text } from "drizzle-orm/pg-core";

export const Test = pgTable(
  "Test",
  {
    id: integer().primaryKey(),
    nullable: boolean(),
    array: text().array().notNull(),
    nestedArray: jsonb().notNull(),
    object: jsonb().notNull(),
  }
);
`);
  expect(sql).toEqual([
    `CREATE TABLE "Test" (
\t"id" integer PRIMARY KEY NOT NULL,
\t"nullable" boolean,
\t"array" text[] NOT NULL,
\t"nestedArray" jsonb NOT NULL,
\t"object" jsonb NOT NULL
);
`,
  ]);

  expect((await generateSqliteTest({ Test })).ts).toContain(`array: text({
      mode: "json",
    }).notNull(),`);
});

it('models', async () => {
  const Test = Model(
    {
      name: 'Test',
      key: ['id', 'test1'],
      indexes: [{ fields: ['test1', 'test2'] }, { fields: ['test2'], where: `"test2" <> ''` }],
      uniques: [{ fields: ['id', 'test1', 'test2'] }],
    },
    { id: S.String(), test1: Unique(S.String()), test2: S.String() },
  );

  const { ts, sql } = await generatePostgresTest({ Test });
  expect(ts).toEqual(`import { index, pgTable, primaryKey, text, unique } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";

export const Test = pgTable(
  "Test",
  {
    id: text().notNull(),
    test1: text().notNull().unique(),
    test2: text().notNull(),
  },
  (t) => [
    primaryKey({
      columns: [t.id, t.test1]
    }),
    unique("Test_id_test1_test2_key").on(t.id, t.test1, t.test2),
    index("Test_test1_test2_idx").on(t.test1, t.test2),
    index("Test_test2_idx").on(t.test2).where(sql.raw("\\"test2\\" <> ''")),
  ]
);
`);
  expect(sql).toEqual([
    `CREATE TABLE "Test" (
\t"id" text NOT NULL,
\t"test1" text NOT NULL,
\t"test2" text NOT NULL,
\tCONSTRAINT "Test_id_test1_pk" PRIMARY KEY("id","test1"),
\tCONSTRAINT "Test_test1_unique" UNIQUE("test1"),
\tCONSTRAINT "Test_id_test1_test2_key" UNIQUE("id","test1","test2")
);
`,
    `CREATE INDEX "Test_test1_test2_idx" ON "Test" USING btree ("test1","test2");`,
    `CREATE INDEX "Test_test2_idx" ON "Test" USING btree ("test2") WHERE "test2" <> '';`,
  ]);

  expect(() => generateDrizzleSchemas({ dialect: 'mysql' }, { 'test.ts': { Test } })).toThrow(
    'Partial indexes are not supported by MySQL',
  );
});

it('database schemas', async () => {
  const TestEnum = S.Enum({ a: {} }, { dbSchema: 'other' });
  const Test = Model({ name: 'Test', key: ['id'], dbSchema: 'other' }, { id: S.String(), enum: TestEnum });

  const { ts, sql } = await generatePostgresTest({ TestEnum, Test });
  expect(ts).toEqual(`import { pgSchema, text } from "drizzle-orm/pg-core";

export const otherSchema = pgSchema("other");
export const TestEnum = otherSchema.enum("TestEnum", ["a"]);
export const Test = otherSchema.table(
  "Test",
  {
    id: text().primaryKey(),
    enum: TestEnum().notNull(),
  }
);
`);
  expect(sql).toEqual([
    `CREATE SCHEMA "other";\n`,
    `CREATE TYPE "other"."TestEnum" AS ENUM('a');`,
    `CREATE TABLE "other"."Test" (
\t"id" text PRIMARY KEY NOT NULL,
\t"enum" "other"."TestEnum" NOT NULL
);
`,
  ]);
});

it('relations', async () => {
  const Test1 = Model(
    { name: 'Test1', key: ['id'] },
    { id: S.String(), nullableId: S.Nullable(S.String()), parentId: S.Nullable(S.String()) },
  );
  const Test2 = Model({ name: 'Test2', key: ['id'] }, { id: S.String(), arrayId: Unique(S.String()) });

  const schemas = {
    Test1,
    Test2,
    RelOneToOne: ModelRelation(Test1, 'oneToOne', ['id'], Test2, 'oneToOneRev', ['id']),
    RelNullable: ModelRelation(Test1, 'nullable', ['nullableId'], Test2, 'nullableRev', ['id'], {
      onDelete: 'Cascade',
      onUpdate: 'SetNull',
    }),
    RelArray: ModelRelation(Test2, 'array', ['arrayId'], Test1, 'arrayRev', ['id']),
    RelParent: ModelRelation(Test1, 'parent', ['parentId'], Test1, 'children', ['id']),
  };

  const { ts, sql } = await generatePostgresTest(schemas);
  expect(ts).toEqual(`import { foreignKey, pgTable, text } from "drizzle-orm/pg-core";
import { relations } from "drizzle-orm";

export const Test1 = pgTable(
  "Test1",
  {
    id: text().primaryKey(),
    nullableId: text(),
    parentId: text(),
  },
  (t) => [
    foreignKey({
      columns: [t.id],
      foreignColumns: [Test2.id],
    }),
    foreignKey({
      columns: [t.nullableId],
      foreignColumns: [Test2.id],
    }).onDelete("cascade").onUpdate("set null"),
    foreignKey({
      columns: [t.parentId],
      foreignColumns: [t.id],
    }),
  ]
);
export const Test1Relations = relations(
  Test1,
  ({ one, many }) => ({
    oneToOne: one(
      Test2,
      {
        fields: [Test1.id],
        references: [Test2.id],
        relationName: "oneToOne",
      }
    ),
    nullable: one(
      Test2,
      {
        fields: [Test1.nullableId],
        references: [Test2.id],
        relationName: "nullable",
      }
    ),
    parent: one(
      Test1,
      {
        fields: [Test1.parentId],
        references: [Test1.id],
        relationName: "parent",
      }
    ),
    arrayRev: one(
      Test2,
      {
        relationName: "array",
      }
    ),
    children: many(
      Test1,
      {
        relationName: "parent",
      }
    ),
  })
);
export const Test2 = pgTable(
  "Test2",
  {
    id: text().primaryKey(),
    arrayId: text().notNull().unique(),
  },
  (t) => [
    foreignKey({
      columns: [t.arrayId],
      foreignColumns: [Test1.id],
    }),
  ]
);
export const Test2Relations = relations(
  Test2,
  ({ one, many }) => ({
    array: one(
      Test1,
      {
        fields: [Test2.arrayId],
        references: [Test1.id],
        relationName: "array",
      }
    ),
    oneToOneRev: one(
      Test1,
      {
        relationName: "oneToOne",
      }
    ),
    nullableRev: many(
      Test1,
      {
        relationName: "nullable",
      }
    ),
  })
);
`);
  expect(sql).toEqual([
    `CREATE TABLE "Test1" (
\t"id" text PRIMARY KEY NOT NULL,
\t"nullableId" text,
\t"parentId" text
);
`,
    `CREATE TABLE "Test2" (
\t"id" text PRIMARY KEY NOT NULL,
\t"arrayId" text NOT NULL,
\tCONSTRAINT "Test2_arrayId_unique" UNIQUE("arrayId")
);
`,
    `ALTER TABLE "Test1" ADD CONSTRAINT "Test1_id_Test2_id_fk" FOREIGN KEY ("id") REFERENCES "public"."Test2"("id") ON DELETE no action ON UPDATE no action;`,
    `ALTER TABLE "Test1" ADD CONSTRAINT "Test1_nullableId_Test2_id_fk" FOREIGN KEY ("nullableId") REFERENCES "public"."Test2"("id") ON DELETE cascade ON UPDATE set null;`,
    `ALTER TABLE "Test1" ADD CONSTRAINT "Test1_parentId_Test1_id_fk" FOREIGN KEY ("parentId") REFERENCES "public"."Test1"("id") ON DELETE no action ON UPDATE no action;`,
    `ALTER TABLE "Test2" ADD CONSTRAINT "Test2_arrayId_Test1_id_fk" FOREIGN KEY ("arrayId") REFERENCES "public"."Test1"("id") ON DELETE no action ON UPDATE no action;`,
  ]);
});

it('splits schemas into files', async () => {
  const Test1 = Model({ name: 'Test1', key: ['id'] }, { id: S.String() });
  const Test2 = Model({ name: 'Test2', key: ['id'] }, { id: S.String(), test1Id: S.String() });

  const res = generateDrizzleSchemas(
    { dialect: 'sqlite' },
    {
      'test1.ts': { Test1 },
      'test2.ts': { Test2, Rel: ModelRelation(Test2, 'test1', ['test1Id'], Test1, 'test2s', ['id']) },
    },
  );
  expect(res['test1.ts']).toContain(`import { Test2 } from "./test2.js";`);
  expect(res['test2.ts']).toContain(`import { Test1 } from "./test1.js";`);
  expect(await generateSql('sqlite', res)).toHaveLength(2);
});
